// Rendering for this feature. State changes are handled by app.js and the domain models.
function sessionPage(){
  const s=state.session;
  if(s.phase==='planning')return`${pageHeading('Your type is set','Now, set<br><em>the scene.</em>','Add the days, time ranges and places that work for you before searching.')}<section class="panel">${preferenceSummary(s.preferences)}${button('Choose when & where','navigate','primary','data-view="availability"','calendar')}</section><button class="why-link" data-action="change-type">Change what I’m looking for ${icon('edit')}</button>`;
  if(s.phase==='searching')return`${pageHeading('A little anticipation','Finding your<br><em>sample connection.</em>')}<section class="search-scene" aria-live="polite"><div class="search-hearts" aria-hidden="true"><span>${icon('heart',true)}</span><span>${icon('spark')}</span><span>${icon('heart',true)}</span></div><h2>Looking for a little common ground.</h2><p>Personality, intentions and bill comfort first. Shared plans where possible.</p><div class="search-dots" aria-hidden="true"><i></i><i></i><i></i></div><p class="caption">A short demo search animation. Matching uses local sample profiles; no live people are being contacted.</p>${button('Skip animation','finish-search','secondary','','')}${button('Back to my plans','cancel-search','plain','','')}</section>`;
  if(s.phase==='empty')return`${pageHeading('Your preferences matter','No sample spark<br><em>this time.</em>','None of the remaining sample profiles fits your personality boundaries and bill preferences.')}<section class="panel empty-state plum-card"><span class="empty-icon">${icon('heart')}</span><h2>Keep your type. Change the plan.</h2><p>You can explore different answers or review your own profile and bill choices. There’s no charge to try again.</p>${button('Explore my preferences','change-type')}${button('Review my profile','onboarding','secondary','','')}</section>`;
  if(s.phase==='declined')return declinedPage();
  return introductionPage();
}
function planDetails(plan,withImage=false){const v=venueById(plan.venueId);return`${withImage?`<img class="proposal-photo" src="assets/${v.photo}" alt="Illustrative ${esc(v.name)} dining space">`:''}<div class="plan-lines"><div>${icon('calendar')}<span><strong>${dateLabel(plan.timestamp,{weekday:'long',month:'short',day:'numeric'})}</strong><span>${timeLabel(plan.timestamp)} · one hour · Vancouver time</span></span></div><div>${icon('pin')}<span><strong>${esc(v.name)}</strong><span>${esc(v.area)} · fictional venue</span></span></div><div>${icon('coffee')}<span><strong>${esc(Dating.billText(plan.billMode))}</strong><span>~C$${v.price}/person before deciding who covers it</span></span></div></div>`;}
function comparisonGrid(s,c){return`<div class="comparison-grid"><section><h3>Your choices</h3>${availabilitySummary(s.availability)}</section><section><h3>Their choices</h3>${availabilitySummary(c)}</section></div>`;}
function availabilitySummary(a){return`<div class="comparison-times">${a.windows.map(w=>`<span>${dayLabel(w.date)} · ${displayTime(w.start)}–${displayTime(w.end)}</span>`).join('')||'<span>No saved time range</span>'}</div><div class="comparison-places">${a.venueIds.map(id=>`<span>${esc(venueById(id)?.name||'')}</span>`).join('')}</div>`;}
function introductionPage(){
  const s=state.session,c=s.person,[prompt,answer]=matchPrompt(c),shared=s.preferences.interests.filter(t=>c.interests.includes(t));
  const intro=`<article class="personality-card intro-personality"><div class="mystery-cover"><span class="mystery-label">${icon('lock')} Your profiles stay hidden</span><div class="mystery-cards" aria-hidden="true"><span class="paper-card paper-one">${icon('heart',true)}</span><span class="paper-card paper-two">?</span></div><span class="cover-caption">A possible connection. A plan to agree on.</span></div><div class="personality-body"><span class="sample-label">Sample introduction #${c.id}</span><h2>${esc(prompt)}</h2><p class="prompt-answer">${esc(answer)}</p>${shared.length?`<div class="common-ground"><span>A little of what you were looking for</span>${sharedChips(shared)}</div>`:''}<div class="match-facts"><span>${icon('heart')}${esc(c.intent)}</span><span>${icon('pin')}${s.stretched?'Slightly outside your age or distance range':'Within your '+s.preferences.radius+' km radius'}</span>${Trust.record(c.id,state.reliabilityOverrides)?.verified?`<span class="verified-fact">${icon('seal')}ID & selfie verified</span>`:''}</div></div></article>`;
  if(s.phase==='found')return`${pageHeading(s.isReschedule?'A change to your confirmed date':'Found a sample introduction',s.isReschedule?'Same spark.<br><em>A different plan?</em>':'A little spark.<br><em>Now, a real plan.</em>',s.isReschedule?'Your original date stays confirmed until you both accept and confirm a new plan.':'You fit each other’s basic preferences. A date is confirmed only after you both agree.')}${intro}<button class="why-link" data-action="why">${icon('spark')} Why you two? ${icon('chevron')}</button><section class="proposal-section"><h2>${s.suggested?'A plan that overlaps.':'Same vibe. Different plans.'}</h2><p>${s.suggested?'Here’s a time, place and bill arrangement that fits both sets of choices.':'The time or restaurant choices don’t overlap yet. Compare them and decide whether either of you can adjust.'}</p>${s.suggested?`<div class="panel suggested-plan">${planDetails(s.suggested)}${button('Ask them to confirm this plan','send-overlap','primary','','heart')}</div>`:''}${s.suggested?`<details class="compare-details"><summary>Compare both schedules ${icon('down')}</summary>${comparisonGrid(s,c)}</details>`:comparisonGrid(s,c)}${!s.suggested?`<div class="proposal-actions">${button('I can do their plan','adopt-their-plan','primary','','heart')}${button('Ask them to try my plan','send-my-plan','secondary','','arrow')}</div>`:''}${button('Offer another time or place','edit-proposal','secondary','','edit')}<p class="caption">The bill arrangement is shown in every offer. A change applies to this date only.</p></section>${trustCard(c)}<button class="why-link" data-action="rematch">Not feeling this plan? Try another introduction ${icon('arrow')}</button>${!s.isReschedule?`<button class="why-link" data-action="change-type">Change what I’m looking for ${icon('edit')}</button><p class="page-note">Changing your type ends this unconfirmed introduction. Your saved type changes only if you save new answers.</p>`:''}`;
  const p=s.proposal,errors=Dating.proposalErrors(p,state.profile,c),agreed=s.phase==='agreed';
  return`${pageHeading(agreed?'You’ve both accepted':p.author==='partner'?'A demo reply has arrived':'Your demo invitation is ready',agreed?'You’re on the<br><em>same page.</em>':p.author==='partner'?'A little<br><em>meet-in-the-middle.</em>':'The invitation’s<br><em>with them.</em>',s.isReschedule?'Your original date stays confirmed until you both agree to this change.':agreed?'One last review before confirming this demo date.':'An introduction becomes a date when you both accept the same plan.')}<section class="proposal-card">${planDetails(p,true)}${p.note?`<div class="proposal-message"><span>${p.author==='partner'?'Their sample note':'Your note'}</span><p>${esc(p.note)}</p></div>`:''}<div class="agreement-status"><span class="${p.youAccepted?'saved-status':''}">${icon(p.youAccepted?'check':'clock')} You ${p.youAccepted?'accepted':'haven’t accepted yet'}</span><span class="${p.partnerAccepted?'saved-status':''}">${icon(p.partnerAccepted?'check':'clock')} They ${p.partnerAccepted?'accepted':'haven’t replied yet'}</span></div></section>${Object.keys(errors).length?`<div class="inline-alert" role="alert">${Object.values(errors).map(esc).join(' ')} Review or change this proposal.</div>`:''}${agreed?agreementReview():p.author==='partner'?`<div class="proposal-actions">${button('This works for me','accept-counter','primary','','heart')}${button('Suggest another plan','edit-proposal','secondary','','edit')}</div>`:`<p class="waiting-label">${icon('bell')} Waiting for a simulated reply</p>${demoReplies()}`}${!agreed?'<p class="page-note">Prototype: no real notification is sent. Use the demo reply controls to try both sides.</p>':''}<div class="proposal-actions">${agreed||p.author!=='partner'?button('Change my proposal','edit-proposal','secondary','','edit'):''}${button(s.isReschedule?'Keep our original date':'We can’t align — rematch',s.isReschedule?'withdraw-change':'rematch','plain','','')}</div>`;
}
function trustCard(c){
  const r=Trust.record(c.id,state.reliabilityOverrides);if(!r)return'';
  if(!(isMember()||state.unlocks.includes(DateLifecycle.introductionKey(state.session))))return`<section class="trust-card locked"><div class="trust-row"><span class="row-icon violet">${icon('star')}</span><span class="row-copy"><strong>Their rating & show-up record</strong><span>Know who you’re meeting · C$1.99</span></span>${button('Unlock','unlock-trust','primary',`data-value="${c.id}"`,'lock')}</div><button class="why-link" data-action="membership">Every record included with blinddate+ · from ${Plans.money(Plans.monthly.intro)} ${icon('chevron')}</button></section>`;
  return`<section class="trust-card"><div class="trust-head"><h2>Their record</h2><span class="rating">${icon('star',true)} ${r.rating.toFixed(1)} <small>· ${r.dates} dates</small></span></div><ul class="trust-facts"><li class="${r.noShows?'warn':'good'}">${icon(r.noShows?'warning':'check')}${r.noShows?r.noShows+' no-show'+(r.noShows>1?'s':''):'Showed up to every date'}</li><li class="${r.lateCancels?'warn':'good'}">${icon(r.lateCancels?'clock':'check')}${r.lateCancels?r.lateCancels+' late cancellation'+(r.lateCancels>1?'s':''):'No late cancellations'}</li><li class="${r.verified?'good':''}">${icon(r.verified?'seal':'info')}${r.verified?'ID & selfie verified':'Not verified yet'}</li></ul><div class="shared-chips">${r.tags.map(t=>`<span>${esc(t)}</span>`).join('')}</div><p class="caption">Fictional sample record. A live app would require a confirmed date before accepting a review.</p></section>`;
}
function demoReplies(){const revision=state.session.proposal.revision;return`<details class="demo-replies"><summary>Try a demo reply ${icon('down')}</summary><p>No real partner is connected. Choose how the sample person responds.</p><div>${button('They accept this plan','demo-accept','secondary',`data-revision="${revision}"`,'check')}${button('They suggest another plan','demo-counter','secondary',`data-revision="${revision}"`,'calendar')}${button('They can’t make it','demo-decline','secondary',`data-revision="${revision}"`,'close')}</div></details>`;}
function agreementReview(){const p=state.session.proposal,cutoff=p.timestamp-86400000;return`<section class="agreement-review"><h2>A first hello, on your terms.</h2><dl class="review-details"><div><dt>Introduction fee</dt><dd>C$0 · first introduction</dd></div><div><dt>Food & drinks</dt><dd>${esc(Dating.billText(p.billMode))}</dd></div></dl><div class="cancellation-summary"><div>${icon('clock')}<h3>Free cancellation until</h3></div><strong>${dateLabel(cutoff)} at ${timeLabel(cutoff)} PT</strong><p>After that: example C$20 fee. Safety concerns and emergencies are exempt. Leaving a date early has no fee.</p></div>${markerBuilder()}<label class="checkbox-label"><input id="agreement-consent" type="checkbox"><span>I accept this exact time, place and bill arrangement, and understand the example cancellation policy. This is a demo with no real reservation or payment.</span></label>${button('Confirm demo date','confirm-agreement','primary','disabled','heart')}</section>`;}
function markerSelect(label,key,options,value,blank){return`<div class="field"><label for="marker-${key}">${label}</label><select class="input" id="marker-${key}" data-marker-field="${key}"><option value="">${blank}</option>${options.filter(Boolean).map(o=>`<option ${value===o?'selected':''}>${esc(o)}</option>`).join('')}</select></div>`;}
function markerBuilder(){const m=Trust.normalizeMarker(state.session.marker);return`<div class="marker-builder"><h3>How they’ll recognise you</h3><p class="body-small">Picked from lists, so no names, handles or numbers can slip in. They see it on the day; you’ll see theirs.</p><div class="field-grid">${markerSelect('Colour','colour',Trust.colours,m.colour,'Choose')}${markerSelect('I’ll be wearing','top',Trust.tops,m.top,'Choose')}</div><div class="field-grid">${markerSelect('Also','extra',Trust.extras,m.extra,'None')}${markerSelect('Arriving','arrival',Trust.arrivals,m.arrival,'Skip')}</div><div class="field-grid car-fields" ${m.arrival==='by car'?'':'hidden'}>${markerSelect('Car colour','carColour',Trust.colours,m.carColour,'Choose')}${markerSelect('Car type','carType',Trust.carTypes,m.carType,'Choose')}</div><p class="marker-preview" data-marker-preview>${esc(Trust.markerText(m)||'Choose a colour and what you’ll wear.')}</p></div>`;}
function declinedPage(){const s=state.session;return`${pageHeading('Sometimes the plans don’t line up','Good chemistry.<br><em>Wrong timing.</em>',s.isReschedule?'They couldn’t accept the change. Your original date is still confirmed.':'This introduction hasn’t become a date. Neither of you has to change a boundary.')}<section class="panel empty-state plum-card"><span class="empty-icon">${icon('calendar')}</span><h2>${s.isReschedule?'Keep the original, or review it.':'Find a plan that feels easy.'}</h2><p>No fee applies to an unconfirmed introduction.</p>${button(s.isReschedule?'Keep our original date':'Try another introduction',s.isReschedule?'withdraw-change':'rematch','primary','','heart')}${button('Offer a different plan','edit-proposal','secondary','','edit')}</section>`;}


function matchPrompt(person) {
  const prompts={
    '021':['The way to my heart is…','A trail with a view, saying hi to every dog, and cooking something together.'],
    '032':['My ideal first date…','A tiny coffee shop, a conversation about art, and taking the long way home.'],
    '048':['We’ll get along if…','You can turn cooking dinner into a kitchen concert. Bonus points for a good playlist.'],
    '055':['A great night looks like…','Live music, an unplanned detour, and someone who makes me laugh.'],
    '063':['My kind of weekend…','A morning workout, something homemade, and dreaming up our next little trip.'],
    '071':['I’ll fall for you if…','You bring a book recommendation and stay for a second cup of coffee.'],
    '084':['My simple pleasures…','Sunrise runs, my mom’s cooking, and planning trips I actually take.'],
    '092':['Let’s debate…','Whether a gig is better from the front row or the back with a good view.'],
    '105':['Green flag I look for…','Someone who asks the dog’s name before the owner’s.'],
    '117':['Typical Sunday…','An early hike, a big brunch, and a nap I’ll defend with my life.']
  };
  return prompts[person.id]||['A little about me…','Good conversation is a pretty good place to start.'];
}
